# Cargar todos los sorteos del JSON
for s in sorteos_json:
    obj, created = Sorteo.objects.get_or_create(
        nombre=s["nombre"],
        defaults={
            "activo": s["activo"],
            "horarios": s["horarios"],
            "creado_en": timezone.now(),
            "actualizado_en": timezone.now()
        }
    )
    if created:
        print(f"✅ Creado: {s['nombre']}")
    else:
        print(f"⏭️ Ya existe: {s['nombre']}")

